command:
// Removes enhanced copies of class abilities from actors that cannot use them.
// Only touches abilities the Enhanced Abilities compendium marks as class gated (they carry a
// prerequisite); actors that meet the prerequisite keep theirs. Lists everything first. GM only.
const api = game.modules.get('draw-steel-combat-tools').api;
const preview = await api.cleanupEnhancedAbilities();
if (!preview.removed) {
  ui.notifications.info('DSCT: nothing to clean up.');
} else {
  const list = preview.actors.slice(0, 40).map(a => `<li>${a}</li>`).join('');
  const more = preview.actors.length > 40 ? `<p>and ${preview.actors.length - 40} more, see the console.</p>` : '';
  const ok = await foundry.applications.api.DialogV2.confirm({
    window: { title: 'Clean Up Enhanced Abilities' },
    content: `<p>Remove <strong>${preview.removed}</strong> enhanced ability copies from actors that do not meet their prerequisite?</p><p>${preview.kept} copies on actors that qualify will be kept.</p><ul>${list}</ul>${more}`,
    rejectClose: false,
  });
  if (ok) await api.cleanupEnhancedAbilities({ apply: true });
}
